def check_sequence(n, a, max_k=5):
    """
    Checks if the sequence {a_k} remains in integers up to max_k for given n and a.
    Returns True if all terms are integers, False otherwise.
    """
    a_prev = a

    # k=0: a_0 = a (integer by assumption)

    for k in range(1, max_k + 1):
        # a_k = a_{k-1}/k + k^{n-1}

        if a_prev % k != 0:
            # If a_{k-1} is not divisible by k, then a_k will not be an integer
            # because k^{n-1} is an integer.
            # We must ensure a_{k-1} / k is an integer.
            return False

        a_k = (a_prev // k) + (k**(n - 1))
        a_prev = a_k

    return True

