def check_recurrence(n, k_max):
    # Candidate C formula for a_k: a_k = (1/k!) * (a + sum_{j=1}^k j! * j^(n-1))
    # We check if this satisfies a_k = a_{k-1}/k + k^(n-1)

    def calculate_C_formula(k, a, n):
        if k == 0:
            return a

        S_k = 0
        for j in range(1, k + 1):
            # j! * j^(n-1)
            try:
                j_fact = math.factorial(j)
                j_pow = j**(n - 1)
                S_k += j_fact * j_pow
            except OverflowError:
                # Handle large numbers if necessary, but for checking properties, small k is enough.
                return "OVERFLOW"

        # a_k = (a + S_k) / k!
        return (a + S_k) / math.factorial(k)

    def calculate_recurrence(k, a, n):
        if k == 0:
            return a

        a_prev = calculate_recurrence(k - 1, a, n)
        return a_prev / k + k**(n - 1)

    import math

    # Let's choose arbitrary starting values for a, e.g., a=1.
    a = 1 

    for k in range(1, k_max + 1):
        C_val = calculate_C_formula(k, a, n)
        R_val = calculate_recurrence(k, a, n)

        # Due to floating point inaccuracies, we check closeness
        if abs(C_val - R_val) > 1e-9:
            print(f"Mismatch found at k={k} for n={n}")
            print(f"C formula: {C_val}, Recurrence: {R_val}")
            return False

    return True

